window.PRIME_getClubId = function(){
  try {
    var parts = String(location.pathname || "").split("/");
    for (var i = parts.length - 1; i >= 0; i--) {
      var p = parts[i];
      if (!p || p.indexOf(".html") !== -1) continue;
      if (window.PRIME_DIR_TO_CLUB[p]) return window.PRIME_DIR_TO_CLUB[p];
      var low = p.toLowerCase();
      for (var k in window.PRIME_DIR_TO_CLUB) { if (k.toLowerCase() === low) return window.PRIME_DIR_TO_CLUB[k]; }
    }
  } catch(e){}
  return "arnau";
};
window.PRIME_resolveSpec = function(clubId, mapZone){
  var m = (window.PRIME_ZONE_MAP[clubId]||{})[mapZone];
  if (m && window.PRIME_SPECS[clubId] && window.PRIME_SPECS[clubId][m]) return { key: m, data: window.PRIME_SPECS[clubId][m] };
  // fallback: direct match
  if (window.PRIME_SPECS[clubId] && window.PRIME_SPECS[clubId][mapZone]) return { key: mapZone, data: window.PRIME_SPECS[clubId][mapZone] };
  return null;
};
